import re
from collections import defaultdict
import jiwer

NUM = {"ek": 1, "do": 2, "teen": 3, "chaar": 4, "char": 4, "paanch": 5, "panch": 5,
       "chhe": 6, "saat": 7, "aath": 8, "nau": 9, "das": 10, "bees": 20,
       "pachees": 25, "tees": 30, "chaalees": 40, "pachaas": 50, "sattar": 70,
       "dedh": 1.5, "dhai": 2.5}
SCALE = {"sau": 100, "hazaar": 1_000, "hazar": 1_000, "lakh": 1_00_000, "crore": 1_00_00_000}
ADJUST = {"saadhe": 0.5, "sava": 0.25, "paune": -0.25}   # 3½, 2¼, 3¾ ...

def words_to_rupees(text):
    """'saadhe teen hazaar' -> 3500, 'dhai lakh' -> 250000, '12,500' -> 12500."""
    total, cur, adj, seen = 0, 0, 0, False
    for w in re.findall(r"[a-z]+|\d[\d,]*", text.lower()):
        if w[0].isdigit():
            cur += int(w.replace(",", "")); seen = True
        elif w in ADJUST:
            adj = ADJUST[w]
        elif w in NUM:
            cur += NUM[w]; seen = True
        elif w in SCALE and seen:
            total += ((cur or 1) + adj) * SCALE[w]
            cur, adj = 0, 0
    return round(total + cur) if seen else None

def inr(n):
    """Indian digit grouping: 250000 -> '2,50,000'."""
    s = str(n)
    if len(s) <= 3:
        return s
    head, tail = s[:-3], s[-3:]
    head = re.sub(r"(\d)(?=(\d\d)+$)", r"\1,", head)
    return f"{head},{tail}"

def score_by_language(rows):
    """rows: (language, reference, hypothesis) from your own transcribed calls."""
    by_lang = defaultdict(lambda: ([], []))
    for lang, ref, hyp in rows:
        by_lang[lang][0].append(ref)
        by_lang[lang][1].append(hyp)
    return {lang: (jiwer.wer(refs, hyps), jiwer.cer(refs, hyps))
            for lang, (refs, hyps) in by_lang.items()}

if __name__ == "__main__":
    for said in ["saadhe teen hazaar", "dhai lakh", "paune chaar hazaar",
                 "teen hazaar paanch sau", "sava do lakh", "premium 12,500 hai"]:
        print(f"{said!r:28} -> ₹{inr(words_to_rupees(said))}")
    rows = [("hi", "mera premium kab due hai", "mera premium kab due hai"),
            ("hi", "policy lapse ho gayi kya", "policy laps ho gayi kya"),
            ("ta", "en policy number sollunga", "en policy nambar sollunga")]
    for lang, (wer, cer) in score_by_language(rows).items():
        print(lang, f"WER {wer:.0%}  CER {cer:.0%}")
